static void *qwen35_checked_calloc_bytes(uint64_t bytes, const char *name) {
    if (bytes == 0) return NULL;
    if (bytes > (uint64_t)SIZE_MAX) {
        fprintf(stderr, "ds4: Qwen native state buffer is too large for this platform: %s=%" PRIu64 " bytes\n",
                name, bytes);
        return NULL;
    }
    void *p = calloc(1, (size_t)bytes);
    if (!p) {
        fprintf(stderr, "ds4: failed to allocate Qwen native state buffer %s=%" PRIu64 " bytes\n",
                name, bytes);
    }
    return p;
}

static void qwen35_native_state_free(qwen35_native_state *st) {
    if (!st) return;
#if !defined(DS4_NO_GPU) && !defined(__APPLE__)
    ds4_gpu_tensor_free(st->gpu_gdn_conv);
    ds4_gpu_tensor_free(st->gpu_gdn_state);
    ds4_gpu_tensor_free(st->gpu_layer_gated);
    ds4_gpu_tensor_free(st->gpu_layer_alpha);
    ds4_gpu_tensor_free(st->gpu_layer_beta);
    ds4_gpu_tensor_free(st->gpu_layer_z);
    ds4_gpu_tensor_free(st->gpu_layer_qkv);
    ds4_gpu_tensor_free(st->gpu_full_kv);
    ds4_gpu_tensor_free(st->gpu_full_heads);
    ds4_gpu_tensor_free(st->gpu_full_v);
    ds4_gpu_tensor_free(st->gpu_full_k);
    ds4_gpu_tensor_free(st->gpu_full_qg);
    ds4_gpu_tensor_free(st->gpu_ffn_mid);
    ds4_gpu_tensor_free(st->gpu_ffn_up);
    ds4_gpu_tensor_free(st->gpu_ffn_gate);
    ds4_gpu_tensor_free(st->gpu_mat_q8);
    ds4_gpu_tensor_free(st->gpu_mat_out);
    ds4_gpu_tensor_free(st->gpu_mat_in);
    ds4_gpu_tensor_free(st->gpu_ffn);
    ds4_gpu_tensor_free(st->gpu_after_attn);
    ds4_gpu_tensor_free(st->gpu_attn);
    ds4_gpu_tensor_free(st->gpu_next);
    ds4_gpu_tensor_free(st->gpu_cur);
    ds4_gpu_tensor_free(st->gpu_argmax_idx);
    ds4_gpu_tensor_free(st->gpu_logits);
    ds4_gpu_tensor_free(st->gpu_norm);
#endif
    free(st->full_scores);
    free(st->full_heads);
    free(st->full_v);
    free(st->full_k);
    free(st->full_qg);
    free(st->mtp_attn_kv);
    free(st->mtp_cat);
    free(st->mtp_pending_hidden);
    free(st->mtp_hidden);
    free(st->q8_xscale);
    free(st->q8_xq);
    free(st->moe_selected);
    free(st->moe_expert_weight);
    free(st->moe_router_probs);
    free(st->moe_router_logits);
    free(st->ffn_gate_up);
    free(st->ffn_down);
    free(st->ffn_mid);
    free(st->ffn_up);
    free(st->ffn_gate);
    free(st->layer_gated);
    free(st->layer_gdn);
    free(st->layer_g);
    free(st->layer_alpha);
    free(st->layer_beta);
    free(st->layer_conv);
    free(st->layer_z);
    free(st->layer_qkv);
    free(st->norm);
    free(st->ffn);
    free(st->after_attn);
    free(st->attn);
    free(st->next);
    free(st->cur);
    free(st->full_attn_kv);
    free(st->gdn_conv);
    free(st->gdn_state);
    memset(st, 0, sizeof(*st));
}

static void qwen35_native_state_reset(qwen35_native_state *st) {
    if (!st) return;
    if (st->gdn_state) memset(st->gdn_state, 0, (size_t)st->plan.gdn_state_f32_bytes_total);
    if (st->gdn_conv) memset(st->gdn_conv, 0, (size_t)st->plan.gdn_conv_f32_bytes_total);
    if (st->full_attn_kv) memset(st->full_attn_kv, 0, (size_t)st->plan.full_attn_kv_f16_bytes_total);
    if (st->mtp_attn_kv) {
        const uint64_t bytes = (uint64_t)st->ctx_size * 2u * st->plan.full_kv_dim * sizeof(uint16_t);
        memset(st->mtp_attn_kv, 0, (size_t)bytes);
    }
    if (st->mtp_pending_hidden) memset(st->mtp_pending_hidden, 0, (size_t)st->n_embd * sizeof(st->mtp_pending_hidden[0]));
    st->mtp_attn_kv_len = 0;
#if !defined(DS4_NO_GPU) && !defined(__APPLE__)
    if (st->gpu_gdn_state) ds4_gpu_tensor_fill_f32(st->gpu_gdn_state, 0.0f, st->plan.gdn_state_f32_bytes_total / sizeof(float));
    if (st->gpu_gdn_conv) ds4_gpu_tensor_fill_f32(st->gpu_gdn_conv, 0.0f, st->plan.gdn_conv_f32_bytes_total / sizeof(float));
    if (st->gpu_full_kv) ds4_gpu_tensor_fill_f32(st->gpu_full_kv, 0.0f, st->gpu_full_kv_bytes / sizeof(float));
    st->gpu_gdn_ready = 0;
    st->gpu_full_kv_ready = 0;
#endif
}

static int qwen35_native_state_alloc(qwen35_native_state *st, const qwen35_config *q, int ctx_size) {
    if (!st || !q || ctx_size <= 0) return 1;
    memset(st, 0, sizeof(*st));
    st->ctx_size = ctx_size;
    st->n_embd = q->n_embd;
    st->plan = qwen35_make_runtime_plan(q, (uint64_t)ctx_size);
    st->gdn_state = qwen35_checked_calloc_bytes(st->plan.gdn_state_f32_bytes_total, "gdn_state");
    if (st->plan.gdn_state_f32_bytes_total && !st->gdn_state) goto fail;
    st->gdn_conv = qwen35_checked_calloc_bytes(st->plan.gdn_conv_f32_bytes_total, "gdn_conv");
    if (st->plan.gdn_conv_f32_bytes_total && !st->gdn_conv) goto fail;
    st->full_attn_kv = qwen35_checked_calloc_bytes(st->plan.full_attn_kv_f16_bytes_total, "full_attn_kv_f16");
    if (st->plan.full_attn_kv_f16_bytes_total && !st->full_attn_kv) goto fail;
    const size_t n_embd = (size_t)q->n_embd;
    st->cur = xmalloc(n_embd * sizeof(st->cur[0]));
    st->next = xmalloc(n_embd * sizeof(st->next[0]));
    st->attn = xmalloc(n_embd * sizeof(st->attn[0]));
    st->after_attn = xmalloc(n_embd * sizeof(st->after_attn[0]));
    st->ffn = xmalloc(n_embd * sizeof(st->ffn[0]));
    st->norm = xmalloc(n_embd * sizeof(st->norm[0]));
    st->layer_qkv = xmalloc((size_t)st->plan.conv_dim * sizeof(st->layer_qkv[0]));
    st->layer_z = xmalloc((size_t)st->plan.value_dim * sizeof(st->layer_z[0]));
    st->layer_conv = xmalloc((size_t)st->plan.conv_dim * sizeof(st->layer_conv[0]));
    st->layer_beta = xmalloc((size_t)q->ssm_dt_rank * sizeof(st->layer_beta[0]));
    st->layer_alpha = xmalloc((size_t)q->ssm_dt_rank * sizeof(st->layer_alpha[0]));
    st->layer_g = xmalloc((size_t)q->ssm_dt_rank * sizeof(st->layer_g[0]));
    st->layer_gdn = xmalloc((size_t)st->plan.value_dim * sizeof(st->layer_gdn[0]));
    st->layer_gated = xmalloc((size_t)st->plan.value_dim * sizeof(st->layer_gated[0]));
    size_t ffn_scratch = q->n_ff;
    if ((size_t)q->n_ff_exp > ffn_scratch) ffn_scratch = q->n_ff_exp;
    if ((size_t)q->n_ff_shexp > ffn_scratch) ffn_scratch = q->n_ff_shexp;
    if (ffn_scratch == 0) ffn_scratch = 1;
    st->ffn_gate = xmalloc(ffn_scratch * sizeof(st->ffn_gate[0]));
    st->ffn_up = xmalloc(ffn_scratch * sizeof(st->ffn_up[0]));
    st->ffn_mid = xmalloc(ffn_scratch * sizeof(st->ffn_mid[0]));
    st->ffn_down = xmalloc(n_embd * sizeof(st->ffn_down[0]));
    st->ffn_gate_up = q->n_ff_exp ? xmalloc((size_t)2u * q->n_ff_exp * sizeof(st->ffn_gate_up[0])) : NULL;
    st->moe_router_logits = q->n_expert ? xmalloc((size_t)q->n_expert * sizeof(st->moe_router_logits[0])) : NULL;
    st->moe_router_probs = q->n_expert ? xmalloc((size_t)q->n_expert * sizeof(st->moe_router_probs[0])) : NULL;
    st->moe_expert_weight = q->n_expert_used ? xmalloc((size_t)q->n_expert_used * sizeof(st->moe_expert_weight[0])) : NULL;
    st->moe_selected = q->n_expert_used ? xmalloc((size_t)q->n_expert_used * sizeof(st->moe_selected[0])) : NULL;
    const size_t q_dim = (size_t)q->n_head * (size_t)q->head_dim;
    const size_t kv_dim = (size_t)q->n_head_kv * (size_t)q->head_dim;
    st->full_qg = xmalloc(2u * q_dim * sizeof(st->full_qg[0]));
    st->full_k = xmalloc(kv_dim * sizeof(st->full_k[0]));
    st->full_v = xmalloc(kv_dim * sizeof(st->full_v[0]));
    st->full_heads = xmalloc(q_dim * sizeof(st->full_heads[0]));
    st->full_scores = xmalloc((size_t)ctx_size * sizeof(st->full_scores[0]));
    const uint64_t mtp_kv_bytes = (uint64_t)ctx_size * 2u * st->plan.full_kv_dim * sizeof(uint16_t);
    st->mtp_attn_kv = q->nextn_predict_layers ? qwen35_checked_calloc_bytes(mtp_kv_bytes, "mtp_attn_kv_f16") : NULL;
    if (q->nextn_predict_layers && mtp_kv_bytes && !st->mtp_attn_kv) goto fail;
    st->mtp_hidden = xmalloc(n_embd * sizeof(st->mtp_hidden[0]));
    st->mtp_pending_hidden = xcalloc(n_embd, sizeof(st->mtp_pending_hidden[0]));
    st->mtp_cat = xmalloc(2u * n_embd * sizeof(st->mtp_cat[0]));
    size_t q8_dim = n_embd;
    if (2u * n_embd > q8_dim) q8_dim = 2u * n_embd;
    if ((size_t)q->n_ff > q8_dim) q8_dim = q->n_ff;
    if ((size_t)q->n_ff_exp > q8_dim) q8_dim = q->n_ff_exp;
    if ((size_t)q->n_ff_shexp > q8_dim) q8_dim = q->n_ff_shexp;
    st->q8_blocks_cap = (q8_dim + 31u) / 32u;
    if (st->q8_blocks_cap == 0) st->q8_blocks_cap = 1;
    st->q8_xq = xmalloc((size_t)st->q8_blocks_cap * 32u);
    st->q8_xscale = xmalloc((size_t)st->q8_blocks_cap * sizeof(st->q8_xscale[0]));
    return 0;

fail:
    qwen35_native_state_free(st);
    return 1;
}

static void qwen35_get_scale_min_k4(int j, const uint8_t *q, uint8_t *d, uint8_t *m) {
    if (j < 4) {
        *d = q[j] & 63u;
        *m = q[j + 4] & 63u;
    } else {
        *d = (q[j + 4] & 0x0fu) | ((q[j - 4] >> 6) << 4);
        *m = (q[j + 4] >> 4) | ((q[j] >> 6) << 4);
    }
}

static int qwen35_dequantize_q4_0_row(float *out, const block_q4_0 *blocks, uint64_t n) {
    if ((n % 32u) != 0) return 1;
    const uint64_t nb = n / 32u;
    for (uint64_t ib = 0; ib < nb; ib++) {
        const block_q4_0 *b = &blocks[ib];
        const float d = f16_to_f32(b->d);
        float *y = out + ib * 32u;
        for (uint32_t j = 0; j < 16u; j++) {
            y[j +  0] = d * (float)((int)(b->qs[j] & 0x0fu) - 8);
            y[j + 16] = d * (float)((int)(b->qs[j] >> 4) - 8);
        }
    }
    return 0;
}

static int qwen35_dequantize_q4_1_row(float *out, const block_q4_1 *blocks, uint64_t n) {
    if ((n % 32u) != 0) return 1;
    const uint64_t nb = n / 32u;
    for (uint64_t ib = 0; ib < nb; ib++) {
        const block_q4_1 *b = &blocks[ib];
        const float d = f16_to_f32(b->d);
        const float m = f16_to_f32(b->m);
        float *y = out + ib * 32u;
        for (uint32_t j = 0; j < 16u; j++) {
            y[j +  0] = m + d * (float)(b->qs[j] & 0x0fu);
            y[j + 16] = m + d * (float)(b->qs[j] >> 4);
        }
    }
    return 0;
}

static void qwen35_dequantize_q2_k_row(float *out, const block_q2_K *blocks, uint64_t n) {
    if ((n % QK_K) != 0) ds4_die("Q2_K row is not QK_K aligned");
    const uint64_t nb = n / QK_K;
    for (uint64_t ib = 0; ib < nb; ib++) {
        const block_q2_K *b = &blocks[ib];
        const float d = f16_to_f32(b->d);
        const float dmin = f16_to_f32(b->dmin);
        const uint8_t *q = b->qs;
        float *y = out + ib * QK_K;

        int is = 0;
        for (int n128 = 0; n128 < QK_K; n128 += 128) {
            for (int shift = 0; shift < 8; shift += 2) {
                uint8_t sc = b->scales[is++];
                float dl = d * (float)(sc & 0x0fu);
                float ml = dmin * (float)(sc >> 4);
                for (int l = 0; l < 16; l++) {
                    *y++ = dl * (float)((q[l] >> shift) & 3u) - ml;
                }

                sc = b->scales[is++];
                dl = d * (float)(sc & 0x0fu);
                ml = dmin * (float)(sc >> 4);
                for (int l = 0; l < 16; l++) {
                    *y++ = dl * (float)((q[l + 16] >> shift) & 3u) - ml;
                }
            }
            q += 32;
        }
    }
}

static void qwen35_dequantize_q3_k_row(float *out, const block_q3_K *blocks, uint64_t n) {
    if ((n % QK_K) != 0) ds4_die("Q3_K row is not QK_K aligned");
    const uint64_t nb = n / QK_K;
    const uint32_t kmask1 = 0x03030303u;
    const uint32_t kmask2 = 0x0f0f0f0fu;

    for (uint64_t ib = 0; ib < nb; ib++) {
        const block_q3_K *b = &blocks[ib];
        const float d_all = f16_to_f32(b->d);
        const uint8_t *q = b->qs;
        const uint8_t *hm = b->hmask;
        uint8_t m = 1;
        uint32_t aux[4] = {0, 0, 0, 0};
        memcpy(aux, b->scales, 12);
        const uint32_t tmp = aux[2];
        aux[2] = ((aux[0] >> 4) & kmask2) | (((tmp >> 4) & kmask1) << 4);
        aux[3] = ((aux[1] >> 4) & kmask2) | (((tmp >> 6) & kmask1) << 4);
        aux[0] = (aux[0] & kmask2) | (((tmp >> 0) & kmask1) << 4);
        aux[1] = (aux[1] & kmask2) | (((tmp >> 2) & kmask1) << 4);
        const int8_t *scales = (const int8_t *)aux;
        float *y = out + ib * QK_K;

        int is = 0;
        for (int n128 = 0; n128 < QK_K; n128 += 128) {
            for (int shift = 0; shift < 4; shift++) {
                float dl = d_all * (float)(scales[is++] - 32);
                for (int l = 0; l < 16; l++) {
                    *y++ = dl * (float)((int8_t)((q[l + 0] >> (2 * shift)) & 3u) -
                                        ((hm[l + 0] & m) ? 0 : 4));
                }

                dl = d_all * (float)(scales[is++] - 32);
                for (int l = 0; l < 16; l++) {
                    *y++ = dl * (float)((int8_t)((q[l + 16] >> (2 * shift)) & 3u) -
                                        ((hm[l + 16] & m) ? 0 : 4));
                }
                m <<= 1;
            }
            q += 32;
        }
    }
}

static void qwen35_dequantize_q4_k_row(float *out, const block_q4_K *blocks, uint64_t n) {
    if ((n % QK_K) != 0) ds4_die("Q4_K row is not QK_K aligned");
    const uint64_t nb = n / QK_K;
    for (uint64_t ib = 0; ib < nb; ib++) {
        const block_q4_K *b = &blocks[ib];
        const float d = f16_to_f32(b->d);
        const float dmin = f16_to_f32(b->dmin);
        float *y = out + ib * QK_K;

        for (int p = 0; p < 4; p++) {
            const uint8_t *q = b->qs + p * 32;
            uint8_t sc0 = 0, m0 = 0, sc1 = 0, m1 = 0;
            qwen35_get_scale_min_k4(2 * p + 0, b->scales, &sc0, &m0);
            qwen35_get_scale_min_k4(2 * p + 1, b->scales, &sc1, &m1);
            const float d0 = d * (float)sc0;
            const float d1 = d * (float)sc1;
            const float min0 = dmin * (float)m0;
            const float min1 = dmin * (float)m1;
            for (int l = 0; l < 32; l++) {
                y[p * 64 + l] = d0 * (float)(q[l] & 0x0fu) - min0;
                y[p * 64 + 32 + l] = d1 * (float)(q[l] >> 4) - min1;
            }
        }
    }
}

static void qwen35_dequantize_q5_k_row(float *out, const block_q5_K *blocks, uint64_t n) {
    if ((n % QK_K) != 0) ds4_die("Q5_K row is not QK_K aligned");
    const uint64_t nb = n / QK_K;
    for (uint64_t ib = 0; ib < nb; ib++) {
        const block_q5_K *b = &blocks[ib];
        const uint8_t *ql = b->qs;
        const uint8_t *qh = b->qh;
        const float d = f16_to_f32(b->d);
        const float dmin = f16_to_f32(b->dmin);
        float *y = out + ib * QK_K;

        uint8_t u1 = 1;
        uint8_t u2 = 2;
        int is = 0;
        for (int p = 0; p < 4; p++) {
            uint8_t sc0 = 0, m0 = 0, sc1 = 0, m1 = 0;
            qwen35_get_scale_min_k4(is + 0, b->scales, &sc0, &m0);
            qwen35_get_scale_min_k4(is + 1, b->scales, &sc1, &m1);
            const float d0 = d * (float)sc0;
            const float d1 = d * (float)sc1;
            const float min0 = dmin * (float)m0;
            const float min1 = dmin * (float)m1;
            for (int l = 0; l < 32; l++) {
                const int q0 = (ql[l] & 0x0f) + ((qh[l] & u1) ? 16 : 0);
                const int q1 = (ql[l] >> 4) + ((qh[l] & u2) ? 16 : 0);
                y[p * 64 + l] = d0 * (float)q0 - min0;
                y[p * 64 + 32 + l] = d1 * (float)q1 - min1;
            }
            ql += 32;
            is += 2;
            u1 <<= 2;
            u2 <<= 2;
        }
    }
}

static void qwen35_dequantize_q6_k_row(float *out, const block_q6_K *blocks, uint64_t n) {
    if ((n % QK_K) != 0) ds4_die("Q6_K row is not QK_K aligned");
    const uint64_t nb = n / QK_K;
    for (uint64_t ib = 0; ib < nb; ib++) {
        const block_q6_K *b = &blocks[ib];
        const uint8_t *ql = b->ql;
        const uint8_t *qh = b->qh;
        const int8_t *sc = b->scales;
        float *y = out + ib * QK_K;
        const float d = f16_to_f32(b->d);

        for (int n128 = 0; n128 < 2; n128++) {
            for (int l = 0; l < 32; l++) {
                const int is = l / 16;
                const int q1 = (ql[l +  0] & 0x0f) | (((qh[l] >> 0) & 0x03) << 4);
                const int q2 = (ql[l + 32] & 0x0f) | (((qh[l] >> 2) & 0x03) << 4);
                const int q3 = (ql[l +  0] >> 4)   | (((qh[l] >> 4) & 0x03) << 4);
                const int q4 = (ql[l + 32] >> 4)   | (((qh[l] >> 6) & 0x03) << 4);
                y[l +  0] = d * (float)sc[is + 0] * (float)(q1 - 32);
                y[l + 32] = d * (float)sc[is + 2] * (float)(q2 - 32);
                y[l + 64] = d * (float)sc[is + 4] * (float)(q3 - 32);
                y[l + 96] = d * (float)sc[is + 6] * (float)(q4 - 32);
            }
            ql += 64;
            qh += 32;
            sc += 8;
            y += 128;
        }
    }
}

static int qwen35_dot_q6_k_row(double *acc_out, const block_q6_K *blocks, const float *x, uint64_t n) {
    if (!acc_out || !blocks || !x || (n % QK_K) != 0) return 1;
    double acc = 0.0;
    const uint64_t nb = n / QK_K;
    for (uint64_t ib = 0; ib < nb; ib++) {
        const block_q6_K *b = &blocks[ib];
        const float d = f16_to_f32(b->d);
        const float *xb = x + ib * QK_K;

        const uint8_t *ql = b->ql;
        const uint8_t *qh = b->qh;
        const int8_t *sc = b->scales;
        for (int n128 = 0; n128 < 2; n128++) {
            const float *x128 = xb + (uint64_t)n128 * 128u;
            for (int l = 0; l < 32; l++) {
                const int is = l / 16;
                const int q1 = (ql[l +  0] & 0x0f) | (((qh[l] >> 0) & 0x03) << 4);
                acc += (double)(d * (float)sc[is + 0] * (float)(q1 - 32)) * (double)x128[l + 0];
            }
            for (int l = 0; l < 32; l++) {
                const int is = l / 16;
                const int q2 = (ql[l + 32] & 0x0f) | (((qh[l] >> 2) & 0x03) << 4);
                acc += (double)(d * (float)sc[is + 2] * (float)(q2 - 32)) * (double)x128[l + 32];
            }
            for (int l = 0; l < 32; l++) {
                const int is = l / 16;
                const int q3 = (ql[l + 0] >> 4) | (((qh[l] >> 4) & 0x03) << 4);
                acc += (double)(d * (float)sc[is + 4] * (float)(q3 - 32)) * (double)x128[l + 64];
            }
            for (int l = 0; l < 32; l++) {
                const int is = l / 16;
                const int q4 = (ql[l + 32] >> 4) | (((qh[l] >> 6) & 0x03) << 4);
                acc += (double)(d * (float)sc[is + 6] * (float)(q4 - 32)) * (double)x128[l + 96];
            }
            ql += 64;
            qh += 32;
            sc += 8;
        }
    }
    *acc_out = acc;
    return 0;
}

static float qwen35_dot_q6_k_row_fast(const block_q6_K *blocks, const float *x, uint64_t n) {
    float acc = 0.0f;
    const uint64_t nb = n / QK_K;
    for (uint64_t ib = 0; ib < nb; ib++) {
        const block_q6_K *b = &blocks[ib];
        const uint8_t *ql = b->ql;
        const uint8_t *qh = b->qh;
        const int8_t *sc = b->scales;
        const float *xb = x + ib * QK_K;
        const float d = f16_to_f32(b->d);

        for (int n128 = 0; n128 < 2; n128++) {
            const float *x128 = xb + (uint64_t)n128 * 128u;
            for (int l = 0; l < 32; l++) {
                const int is = l / 16;
                const int q1 = (ql[l +  0] & 0x0f) | (((qh[l] >> 0) & 0x03) << 4);
                const int q2 = (ql[l + 32] & 0x0f) | (((qh[l] >> 2) & 0x03) << 4);
                const int q3 = (ql[l +  0] >> 4)   | (((qh[l] >> 4) & 0x03) << 4);
                const int q4 = (ql[l + 32] >> 4)   | (((qh[l] >> 6) & 0x03) << 4);
                acc += d * (float)sc[is + 0] * (float)(q1 - 32) * x128[l +  0];
                acc += d * (float)sc[is + 2] * (float)(q2 - 32) * x128[l + 32];
                acc += d * (float)sc[is + 4] * (float)(q3 - 32) * x128[l + 64];
                acc += d * (float)sc[is + 6] * (float)(q4 - 32) * x128[l + 96];
            }
            ql += 64;
            qh += 32;
            sc += 8;
        }
    }
    return acc;
}

static bool qwen35_fast_dot_enabled(void) {
    static bool initialized;
    static bool enabled;
    if (!initialized) {
        const char *env = getenv("DS4_QWEN_FAST_DOT");
        enabled = !(env && env[0] && strcmp(env, "0") == 0);
        initialized = true;
    }
    return enabled;
}

