static int qwen35_layer0_qkv_from_token(ds4_engine *e, int token, float *qkv, uint64_t out_dim) {
    const qwen35_layer_weights *l0 = &e->qwen_weights.layer[0];
    if (!l0->recurrent || !l0->attn_qkv || l0->attn_qkv->dim[1] != out_dim) return 1;
    float *x = xmalloc((size_t)e->qwen_config.n_embd * sizeof(x[0]));
    float *norm = xmalloc((size_t)e->qwen_config.n_embd * sizeof(norm[0]));
    int rc = 0;
    if (qwen35_embed_token_to_f32(e, token, x) != 0 ||
        qwen35_rms_norm_tensor(norm,
                               x,
                               &e->model,
                               l0->attn_norm,
                               e->qwen_config.n_embd,
                               e->qwen_config.rms_eps) != 0 ||
        qwen35_matvec_q4_k(qkv, &e->model, l0->attn_qkv, norm) != 0)
    {
        rc = 1;
    }
    free(norm);
    free(x);
    return rc;
}

int ds4_engine_qwen_ssm_out_test(ds4_engine *e, int token) {
    if (!e || token < 0) return 1;
    if (!ds4_engine_is_qwen(e)) {
        fprintf(stderr, "ds4: --qwen-ssm-out-test requires a Qwen model\n");
        return 2;
    }
    const qwen35_layer_weights *l0 = &e->qwen_weights.layer[0];
    if (!l0->recurrent || !l0->attn_qkv || !l0->ssm_out || l0->ssm_out->type != DS4_TENSOR_Q5_K) {
        fprintf(stderr, "ds4: --qwen-ssm-out-test requires recurrent blk.0 Q5_K ssm_out weights\n");
        return 1;
    }

    const uint64_t qkv_dim = l0->attn_qkv->dim[1];
    const uint64_t value_dim = e->qwen_config.ssm_inner;
    const uint64_t value_off = 2u * (uint64_t)e->qwen_config.ssm_group_count * e->qwen_config.ssm_state;
    if (qkv_dim < value_off + value_dim || l0->ssm_out->dim[0] != value_dim ||
        l0->ssm_out->dim[1] != e->qwen_config.n_embd) {
        return 1;
    }

    float *qkv = xmalloc((size_t)qkv_dim * sizeof(qkv[0]));
    float *out = xmalloc((size_t)e->qwen_config.n_embd * sizeof(out[0]));
    int rc = 0;
    if (qwen35_layer0_qkv_from_token(e, token, qkv, qkv_dim) != 0 ||
        qwen35_matvec_q5_k(out, &e->model, l0->ssm_out, qkv + value_off) != 0)
    {
        rc = 1;
    } else {
        qwen35_print_vec_stats("qwen ssm_out test", token, e->qwen_config.n_embd, tensor_type_name(l0->ssm_out->type), out);
        printf("qwen ssm_out source: layer=0 tensor=blk.0.ssm_out.weight input=attn_qkv_value_slice offset=%" PRIu64 " dim=%" PRIu64 "\n",
               value_off,
               value_dim);
    }
    free(out);
    free(qkv);
    return rc;
}

int ds4_engine_qwen_gdn_param_test(ds4_engine *e, int token) {
    if (!e || token < 0) return 1;
    if (!ds4_engine_is_qwen(e)) {
        fprintf(stderr, "ds4: --qwen-gdn-param-test requires a Qwen model\n");
        return 2;
    }
    const qwen35_layer_weights *l0 = &e->qwen_weights.layer[0];
    if (!l0->recurrent || !l0->attn_qkv || !l0->ssm_conv1d || !l0->ssm_dt ||
        !l0->ssm_a || !l0->ssm_beta || !l0->ssm_alpha ||
        l0->ssm_conv1d->type != DS4_TENSOR_F32 ||
        l0->ssm_dt->type != DS4_TENSOR_F32 ||
        l0->ssm_a->type != DS4_TENSOR_F32 ||
        l0->ssm_beta->type != DS4_TENSOR_F32 ||
        l0->ssm_alpha->type != DS4_TENSOR_F32) {
        fprintf(stderr, "ds4: --qwen-gdn-param-test requires recurrent blk.0 f32 GDN parameter tensors\n");
        return 1;
    }

    const uint64_t qkv_dim = l0->attn_qkv->dim[1];
    const uint64_t conv_dim = 2u * (uint64_t)e->qwen_config.ssm_group_count * e->qwen_config.ssm_state +
                              e->qwen_config.ssm_inner;
    if (qkv_dim != conv_dim ||
        l0->ssm_conv1d->dim[0] != e->qwen_config.ssm_conv_kernel ||
        l0->ssm_conv1d->dim[1] != conv_dim ||
        l0->ssm_beta->dim[0] != e->qwen_config.n_embd ||
        l0->ssm_beta->dim[1] != e->qwen_config.ssm_dt_rank ||
        l0->ssm_alpha->dim[0] != e->qwen_config.n_embd ||
        l0->ssm_alpha->dim[1] != e->qwen_config.ssm_dt_rank ||
        l0->ssm_dt->dim[0] != e->qwen_config.ssm_dt_rank ||
        l0->ssm_a->dim[0] != e->qwen_config.ssm_dt_rank) {
        return 1;
    }

    float *x = xmalloc((size_t)e->qwen_config.n_embd * sizeof(x[0]));
    float *norm = xmalloc((size_t)e->qwen_config.n_embd * sizeof(norm[0]));
    float *qkv = xmalloc((size_t)qkv_dim * sizeof(qkv[0]));
    float *conv = xmalloc((size_t)qkv_dim * sizeof(conv[0]));
    float *beta = xmalloc((size_t)e->qwen_config.ssm_dt_rank * sizeof(beta[0]));
    float *alpha = xmalloc((size_t)e->qwen_config.ssm_dt_rank * sizeof(alpha[0]));
    float *g = xmalloc((size_t)e->qwen_config.ssm_dt_rank * sizeof(g[0]));
    int rc = 0;
    if (qwen35_embed_token_to_f32(e, token, x) != 0 ||
        qwen35_rms_norm_tensor(norm,
                               x,
                               &e->model,
                               l0->attn_norm,
                               e->qwen_config.n_embd,
                               e->qwen_config.rms_eps) != 0 ||
        qwen35_matvec_q4_k(qkv, &e->model, l0->attn_qkv, norm) != 0 ||
        qwen35_matvec_f32(beta, &e->model, l0->ssm_beta, norm) != 0 ||
        qwen35_matvec_f32(alpha, &e->model, l0->ssm_alpha, norm) != 0)
    {
        rc = 1;
    } else {
        const float *conv_w = tensor_data(&e->model, l0->ssm_conv1d);
        const uint64_t kernel = e->qwen_config.ssm_conv_kernel;
        for (uint64_t c = 0; c < qkv_dim; c++) {
            conv[c] = qkv[c] * conv_w[c * kernel + (kernel - 1u)];
        }
        for (uint32_t i = 0; i < e->qwen_config.ssm_dt_rank; i++) {
            beta[i] = sigmoid_stable(beta[i]);
            const float dt_bias = tensor_1d_value(&e->model, l0->ssm_dt, i);
            const float a = tensor_1d_value(&e->model, l0->ssm_a, i);
            g[i] = softplus_stable(alpha[i] + dt_bias) * a;
        }
        qwen35_print_vec_stats("qwen gdn conv0 test", token, (uint32_t)qkv_dim, "f32", conv);
        qwen35_print_vec_stats("qwen gdn beta test", token, e->qwen_config.ssm_dt_rank, "f32", beta);
        qwen35_print_vec_stats("qwen gdn alpha test", token, e->qwen_config.ssm_dt_rank, "f32", alpha);
        qwen35_print_vec_stats("qwen gdn g test", token, e->qwen_config.ssm_dt_rank, "f32", g);
        printf("qwen gdn source: layer=0 input=blk.0.attn_norm(token_embd) conv=zero_state kernel=%u dim=%" PRIu64 " dt_rank=%u\n",
               e->qwen_config.ssm_conv_kernel,
               qkv_dim,
               e->qwen_config.ssm_dt_rank);
    }
    free(g);
    free(alpha);
    free(beta);
    free(conv);
    free(qkv);
    free(norm);
    free(x);
    return rc;
}

int ds4_engine_qwen_gdn_zero_test(ds4_engine *e, int token) {
    if (!e || token < 0) return 1;
    if (!ds4_engine_is_qwen(e)) {
        fprintf(stderr, "ds4: --qwen-gdn-zero-test requires a Qwen model\n");
        return 2;
    }
    const qwen35_layer_weights *l0 = &e->qwen_weights.layer[0];
    if (!l0->recurrent || !l0->attn_qkv || !l0->attn_gate || !l0->ssm_conv1d || !l0->ssm_beta ||
        !l0->ssm_norm || !l0->ssm_out ||
        l0->attn_qkv->type != DS4_TENSOR_Q4_K ||
        l0->attn_gate->type != DS4_TENSOR_IQ3_XXS ||
        l0->ssm_conv1d->type != DS4_TENSOR_F32 ||
        l0->ssm_beta->type != DS4_TENSOR_F32 ||
        l0->ssm_out->type != DS4_TENSOR_Q5_K) {
        fprintf(stderr, "ds4: --qwen-gdn-zero-test requires recurrent blk.0 Q4_K/IQ3_XXS/f32/Q5_K GDN tensors\n");
        return 1;
    }

    const uint32_t n_head = e->qwen_config.ssm_dt_rank;
    const uint32_t n_group = e->qwen_config.ssm_group_count;
    const uint32_t state_dim = e->qwen_config.ssm_state;
    const uint32_t value_head_dim = e->qwen_config.ssm_inner / e->qwen_config.ssm_dt_rank;
    const uint64_t key_dim = (uint64_t)n_group * state_dim;
    const uint64_t value_dim = e->qwen_config.ssm_inner;
    const uint64_t qkv_dim = 2u * key_dim + value_dim;
    if (n_group == 0 ||
        n_head % n_group != 0 ||
        e->qwen_config.ssm_inner % e->qwen_config.ssm_dt_rank != 0 ||
        l0->attn_qkv->dim[1] != qkv_dim ||
        l0->attn_gate->dim[1] != value_dim ||
        l0->ssm_conv1d->dim[0] != e->qwen_config.ssm_conv_kernel ||
        l0->ssm_conv1d->dim[1] != qkv_dim ||
        l0->ssm_beta->dim[1] != n_head ||
        l0->ssm_norm->dim[0] != value_head_dim ||
        l0->ssm_out->dim[0] != value_dim ||
        l0->ssm_out->dim[1] != e->qwen_config.n_embd ||
        value_dim > UINT32_MAX) {
        return 1;
    }

    float *x = xmalloc((size_t)e->qwen_config.n_embd * sizeof(x[0]));
    float *norm = xmalloc((size_t)e->qwen_config.n_embd * sizeof(norm[0]));
    float *qkv = xmalloc((size_t)qkv_dim * sizeof(qkv[0]));
    float *z = xmalloc((size_t)value_dim * sizeof(z[0]));
    float *conv = xmalloc((size_t)qkv_dim * sizeof(conv[0]));
    float *beta = xmalloc((size_t)n_head * sizeof(beta[0]));
    float *gdn = xmalloc((size_t)value_dim * sizeof(gdn[0]));
    float *gated = xmalloc((size_t)value_dim * sizeof(gated[0]));
    float *out = xmalloc((size_t)e->qwen_config.n_embd * sizeof(out[0]));
    int rc = 0;
    if (qwen35_embed_token_to_f32(e, token, x) != 0 ||
        qwen35_rms_norm_tensor(norm,
                               x,
                               &e->model,
                               l0->attn_norm,
                               e->qwen_config.n_embd,
                               e->qwen_config.rms_eps) != 0 ||
        qwen35_matvec_dense_any_scratch(qkv, e, l0->attn_qkv, norm, NULL) != 0 ||
        qwen35_matvec_dense_any_scratch(z, e, l0->attn_gate, norm, NULL) != 0 ||
        qwen35_matvec_f32(beta, &e->model, l0->ssm_beta, norm) != 0)
    {
        rc = 1;
    } else {
        const float *conv_w = tensor_data(&e->model, l0->ssm_conv1d);
        const uint64_t kernel = e->qwen_config.ssm_conv_kernel;
        for (uint64_t c = 0; c < qkv_dim; c++) conv[c] = silu(qkv[c] * conv_w[c * kernel + (kernel - 1u)]);
        for (uint32_t h = 0; h < n_head; h++) beta[h] = sigmoid_stable(beta[h]);

        for (uint32_t h = 0; h < n_head; h++) {
            const uint32_t group = qwen35_gdn_group_for_head(h, n_head, n_group);
            float *qh = conv + (uint64_t)group * state_dim;
            float *kh = conv + key_dim + (uint64_t)group * state_dim;
            qwen35_l2_norm_inplace(qh, state_dim);
            qwen35_l2_norm_inplace(kh, state_dim);
            double qk = 0.0;
            for (uint32_t i = 0; i < state_dim; i++) qk += (double)qh[i] * (double)kh[i];
            const float scale = (float)qk * beta[h];
            const float *vh = conv + 2u * key_dim + (uint64_t)h * value_head_dim;
            float *oh = gdn + (uint64_t)h * value_head_dim;
            for (uint32_t i = 0; i < value_head_dim; i++) oh[i] = vh[i] * scale;
        }

        if (qwen35_gated_rms_norm_heads(gated,
                                        gdn,
                                        z,
                                        &e->model,
                                        l0->ssm_norm,
                                        n_head,
                                        value_head_dim,
                                        e->qwen_config.rms_eps) != 0 ||
            qwen35_matvec_dense_any_scratch(out, e, l0->ssm_out, gated, NULL) != 0)
        {
            rc = 1;
        } else {
            qwen35_print_vec_stats("qwen gdn zero state test", token, (uint32_t)value_dim, "f32", gdn);
            qwen35_print_vec_stats("qwen gdn gated norm test", token, (uint32_t)value_dim, "f32", gated);
            qwen35_print_vec_stats("qwen gdn zero out test", token, e->qwen_config.n_embd, tensor_type_name(l0->ssm_out->type), out);
            printf("qwen gdn zero source: layer=0 state=zero conv=silu heads=%u state_dim=%u value_head_dim=%u\n",
                   n_head,
                   state_dim,
                   value_head_dim);
        }
    }
    free(out);
    free(gated);
    free(gdn);
    free(beta);
    free(conv);
    free(z);
    free(qkv);
    free(norm);
    free(x);
    return rc;
}

int ds4_engine_qwen_gdn_stateful_test(ds4_engine *e, int token0, int token1) {
    if (!e || token0 < 0 || token1 < 0) return 1;
    if (!ds4_engine_is_qwen(e)) {
        fprintf(stderr, "ds4: --qwen-gdn-stateful-test requires a Qwen model\n");
        return 2;
    }
    const qwen35_runtime_plan p = qwen35_make_runtime_plan(&e->qwen_config, 1);
    const uint64_t conv_values = p.gdn_conv_f32_values_per_layer;
    const uint64_t state_values = p.gdn_state_f32_values_per_layer;
    if (!conv_values || !state_values) return 1;

    float *conv_cache = xcalloc((size_t)conv_values, sizeof(conv_cache[0]));
    float *state = xcalloc((size_t)state_values, sizeof(state[0]));
    float *x0 = xmalloc((size_t)e->qwen_config.n_embd * sizeof(x0[0]));
    float *x1 = xmalloc((size_t)e->qwen_config.n_embd * sizeof(x1[0]));
    float *out0 = xmalloc((size_t)e->qwen_config.n_embd * sizeof(out0[0]));
    float *out1 = xmalloc((size_t)e->qwen_config.n_embd * sizeof(out1[0]));
    int rc = 0;
    if (qwen35_embed_token_to_f32(e, token0, x0) != 0 ||
        qwen35_embed_token_to_f32(e, token1, x1) != 0 ||
        qwen35_layer0_gdn_step_out(e, x0, conv_cache, state, out0) != 0 ||
        qwen35_layer0_gdn_step_out(e, x1, conv_cache, state, out1) != 0)
    {
        rc = 1;
    } else {
        qwen35_print_vec_stats("qwen gdn stateful first out test", token0, e->qwen_config.n_embd, "f32", out0);
        qwen35_print_vec_stats("qwen gdn stateful second out test", token1, e->qwen_config.n_embd, "f32", out1);
        qwen35_print_vec_stats("qwen gdn stateful conv cache test", token1, (uint32_t)conv_values, "f32", conv_cache);
        qwen35_print_vec_stats("qwen gdn stateful recurrent state test", token1, (uint32_t)state_values, "f32", state);
        printf("qwen gdn stateful source: layer=0 tokens=%d,%d conv_values=%" PRIu64 " state_values=%" PRIu64 "\n",
               token0,
               token1,
               conv_values,
               state_values);
    }
    free(out1);
    free(out0);
    free(x1);
    free(x0);
    free(state);
    free(conv_cache);
    return rc;
}

int ds4_engine_qwen_session_step_test(ds4_engine *e, int token0, int token1, int ctx_size) {
    if (!e || token0 < 0 || token1 < 0 || ctx_size <= 0) return 1;
    if (!ds4_engine_is_qwen(e)) {
        fprintf(stderr, "ds4: --qwen-session-step-test requires a Qwen model\n");
        return 2;
    }

    ds4_session *s = NULL;
    if (ds4_session_create(&s, e, ctx_size) != 0) return 1;
    const qwen35_runtime_plan p = s->qwen_state.plan;
    if (!s->qwen_state.gdn_conv || !s->qwen_state.gdn_state ||
        p.gdn_conv_f32_values_per_layer == 0 ||
        p.gdn_state_f32_values_per_layer == 0) {
        ds4_session_free(s);
        return 1;
    }

    float *conv_cache = (float *)s->qwen_state.gdn_conv;
    float *state = (float *)s->qwen_state.gdn_state;
    float *x0 = xmalloc((size_t)e->qwen_config.n_embd * sizeof(x0[0]));
    float *x1 = xmalloc((size_t)e->qwen_config.n_embd * sizeof(x1[0]));
    float *out0 = xmalloc((size_t)e->qwen_config.n_embd * sizeof(out0[0]));
    float *out1 = xmalloc((size_t)e->qwen_config.n_embd * sizeof(out1[0]));
    int rc = 0;
    if (qwen35_embed_token_to_f32(e, token0, x0) != 0 ||
        qwen35_embed_token_to_f32(e, token1, x1) != 0 ||
        qwen35_layer0_gdn_step_out(e, x0, conv_cache, state, out0) != 0 ||
        qwen35_layer0_gdn_step_out(e, x1, conv_cache, state, out1) != 0)
    {
        rc = 1;
    } else {
        qwen35_print_vec_stats("qwen session step first out test", token0, e->qwen_config.n_embd, "f32", out0);
        qwen35_print_vec_stats("qwen session step second out test", token1, e->qwen_config.n_embd, "f32", out1);
        qwen35_print_vec_stats("qwen session step conv cache test", token1, (uint32_t)p.gdn_conv_f32_values_per_layer, "f32", conv_cache);
        qwen35_print_vec_stats("qwen session step recurrent state test", token1, (uint32_t)p.gdn_state_f32_values_per_layer, "f32", state);
        printf("qwen session step source: ctx=%d layer=0 tokens=%d,%d conv_values=%" PRIu64 " state_values=%" PRIu64 "\n",
               ctx_size,
               token0,
               token1,
               p.gdn_conv_f32_values_per_layer,
               p.gdn_state_f32_values_per_layer);
    }
    free(out1);
    free(out0);
    free(x1);
    free(x0);
    ds4_session_free(s);
    return rc;
}

static void *qwen35_snapshot_copy_bytes(const void *src, uint64_t bytes) {
    if (bytes == 0) return NULL;
    void *dst = xmalloc((size_t)bytes);
    memcpy(dst, src, (size_t)bytes);
    return dst;
}

static bool qwen35_bytes_equal(const void *a, const void *b, uint64_t bytes) {
    if (bytes == 0) return true;
    return a && b && memcmp(a, b, (size_t)bytes) == 0;
}

int ds4_engine_qwen_snapshot_test(ds4_engine *e, int token0, int token1, int ctx_size) {
    if (!e || token0 < 0 || token1 < 0 || ctx_size <= 0) return 1;
    if (!ds4_engine_is_qwen(e)) {
        fprintf(stderr, "ds4: --qwen-snapshot-test requires a Qwen model\n");
        return 2;
    }

    ds4_session *s = NULL;
    if (ds4_session_create(&s, e, ctx_size) != 0) {
        fprintf(stderr, "ds4: --qwen-snapshot-test failed to create session\n");
        return 1;
    }

    char err[256] = {0};
    ds4_session_snapshot snap = {0};
    const qwen35_native_state *st = &s->qwen_state;
    const qwen35_config *q = &e->qwen_config;
    const uint64_t logits_bytes = (uint64_t)q->n_vocab * sizeof(float);
    const uint64_t mtp_hidden_bytes = (uint64_t)q->n_embd * sizeof(float);
    void *logits0 = NULL;
    void *logits1 = NULL;
    void *gdn_state0 = NULL;
    void *gdn_conv0 = NULL;
    void *full_kv0 = NULL;
    void *mtp_hidden0 = NULL;
    int top0 = -1;
    int top1 = -1;
    uint64_t payload_bytes = 0;
    int rc = 0;

    if (ds4_session_eval(s, token0, err, sizeof(err)) != 0) {
        fprintf(stderr, "ds4: --qwen-snapshot-test failed token0 eval: %s\n", err[0] ? err : "unknown error");
        rc = 1;
        goto done;
    }
    top0 = sample_argmax(s->logits, q->n_vocab);
    payload_bytes = ds4_session_payload_bytes(s);
    if (ds4_session_save_snapshot(s, &snap, err, sizeof(err)) != 0) {
        fprintf(stderr, "ds4: --qwen-snapshot-test failed snapshot save: %s\n", err[0] ? err : "unknown error");
        rc = 1;
        goto done;
    }

    const uint64_t full_kv_live_bytes = qwen35_session_live_full_kv_bytes(s);
    logits0 = qwen35_snapshot_copy_bytes(s->logits, logits_bytes);
    gdn_state0 = qwen35_snapshot_copy_bytes(st->gdn_state, st->plan.gdn_state_f32_bytes_total);
    gdn_conv0 = qwen35_snapshot_copy_bytes(st->gdn_conv, st->plan.gdn_conv_f32_bytes_total);
    full_kv0 = qwen35_snapshot_copy_bytes(st->full_attn_kv, full_kv_live_bytes);
    mtp_hidden0 = qwen35_snapshot_copy_bytes(st->mtp_hidden, mtp_hidden_bytes);

    if (ds4_session_eval(s, token1, err, sizeof(err)) != 0) {
        fprintf(stderr, "ds4: --qwen-snapshot-test failed token1 eval before restore: %s\n",
                err[0] ? err : "unknown error");
        rc = 1;
        goto done;
    }
    logits1 = qwen35_snapshot_copy_bytes(s->logits, logits_bytes);
    top1 = sample_argmax(s->logits, q->n_vocab);

    if (ds4_session_load_snapshot(s, &snap, err, sizeof(err)) != 0) {
        fprintf(stderr, "ds4: --qwen-snapshot-test failed snapshot restore: %s\n", err[0] ? err : "unknown error");
        rc = 1;
        goto done;
    }
    const bool checkpoint_equal = s->checkpoint.len == 1 && s->checkpoint.v[0] == token0;
    const bool logits_equal = qwen35_bytes_equal(s->logits, logits0, logits_bytes);
    const bool gdn_state_equal = qwen35_bytes_equal(st->gdn_state, gdn_state0, st->plan.gdn_state_f32_bytes_total);
    const bool gdn_conv_equal = qwen35_bytes_equal(st->gdn_conv, gdn_conv0, st->plan.gdn_conv_f32_bytes_total);
    const bool full_kv_equal = qwen35_bytes_equal(st->full_attn_kv, full_kv0, full_kv_live_bytes);
    const bool mtp_hidden_equal = e->mtp_draft_tokens <= 1 ||
                                  qwen35_bytes_equal(st->mtp_hidden, mtp_hidden0, mtp_hidden_bytes);
    if (!checkpoint_equal || !logits_equal || !gdn_state_equal || !gdn_conv_equal ||
        !full_kv_equal || !mtp_hidden_equal)
    {
        fprintf(stderr,
                "ds4: --qwen-snapshot-test restored state differs from saved state checkpoint=%d logits=%d gdn_state=%d gdn_conv=%d full_kv=%d mtp_hidden=%d\n",
                checkpoint_equal,
                logits_equal,
                gdn_state_equal,
                gdn_conv_equal,
                full_kv_equal,
                mtp_hidden_equal);
        rc = 1;
        goto done;
    }

    if (ds4_session_eval(s, token1, err, sizeof(err)) != 0) {
        fprintf(stderr, "ds4: --qwen-snapshot-test failed token1 eval after restore: %s\n",
                err[0] ? err : "unknown error");
        rc = 1;
        goto done;
    }
    if (!qwen35_bytes_equal(s->logits, logits1, logits_bytes)) {
        fprintf(stderr, "ds4: --qwen-snapshot-test replay logits differ after restore\n");
        rc = 1;
        goto done;
    }

    printf("qwen snapshot test: token0=%d token1=%d ctx=%d snapshot_bytes=%" PRIu64
           " restored=exact replay=exact top0=%d top1=%d\n",
           token0,
           token1,
           ctx_size,
           payload_bytes,
           top0,
           top1);

done:
    free(mtp_hidden0);
    free(full_kv0);
    free(gdn_conv0);
    free(gdn_state0);
    free(logits1);
    free(logits0);
    ds4_session_snapshot_free(&snap);
    ds4_session_free(s);
    return rc;
}

int ds4_engine_qwen_ffn_gate_test(ds4_engine *e, int token) {
    if (!e || token < 0) return 1;
    if (!ds4_engine_is_qwen(e)) {
        fprintf(stderr, "ds4: --qwen-ffn-gate-test requires a Qwen model\n");
        return 2;
    }
    const qwen35_layer_weights *l0 = &e->qwen_weights.layer[0];
    if (e->qwen_config.moe || !l0->ffn_gate || l0->ffn_gate->type != DS4_TENSOR_Q2_K) {
        fprintf(stderr, "ds4: --qwen-ffn-gate-test requires dense blk.0 Q2_K ffn_gate weights\n");
        return 1;
    }

    const uint64_t out_dim = l0->ffn_gate->dim[1];
    if (l0->ffn_gate->dim[0] != e->qwen_config.n_embd || out_dim > UINT32_MAX) return 1;

    float *x = xmalloc((size_t)e->qwen_config.n_embd * sizeof(x[0]));
    float *gate = xmalloc((size_t)out_dim * sizeof(gate[0]));
    int rc = 0;
    if (qwen35_embed_token_to_f32(e, token, x) != 0 ||
        qwen35_matvec_q2_k(gate, &e->model, l0->ffn_gate, x) != 0)
    {
        rc = 1;
    } else {
        qwen35_print_vec_stats("qwen ffn_gate test", token, (uint32_t)out_dim, tensor_type_name(l0->ffn_gate->type), gate);
        printf("qwen ffn_gate source: layer=0 tensor=blk.0.ffn_gate.weight input=token_embd dim=%" PRIu64 "\n",
               out_dim);
    }
    free(gate);
    free(x);
    return rc;
}

